/* Allowlisted, credential-free diagnostic output. Never write raw replies. */
#include <string.h>
#include <stdlib.h>
#include "diagnostic_report.h"
int ah_report_status(FILE *f,const char *state)
{static const char *states[]={"not_configured","network_down","connecting","sample","connected","retry_wait","disconnected"};unsigned int i;const char *safe="unknown";for(i=0;i<7;++i)if(!strcmp(state,states[i]))safe=states[i];return fprintf(f,"AmiHASS 0.2 diagnostic report\nLocal ABI: 1\nServer state: %s\n",safe)>=0;}
int ah_report_items(FILE *f,const struct AmiHASSEntity *items,unsigned int count)
{static const char *keys[]={"ipc.received","ipc.replies","ipc.bytes_in","ipc.bytes_out","ipc.queries","ipc.lists","ipc.actions","actions.accepted","http.actions","http.polls","http.catalogue","http.completed","http.failed","http.body_bytes","cache.hits","http.timeouts","service.uptime","poll.seconds","entities.active","actions.queued","retry.seconds","http.active","cache.pages","ipc.invalid","http.health","network.running","connection.error","curl.code","http.code","memory.fast.baseline","memory.fast.free","memory.fast.minimum","memory.request.before","memory.request.minimum","memory.request.after","memory.request.peak","memory.reclaimed","memory.requests","memory.flushes","memory.fast.largest","leases.active"};unsigned int i,k,j;if(count>16)return 0;for(i=0;i<count;++i){for(k=0;k<41;++k)if(!strcmp(items[i].id,keys[k]))break;if(k==41)continue;if(!items[i].state[0]||strlen(items[i].state)>11)return 0;for(j=items[i].state[0]=='-' ? 1:0;items[i].state[j];++j)if(items[i].state[j]<'0'||items[i].state[j]>'9')return 0;if(j==0||(j==1&&items[i].state[0]=='-'))return 0;if(fprintf(f,"%s: %s\n",keys[k],items[i].state)<0)return 0;}return !ferror(f);}
